import type pg from 'pg';
import { audit } from './audit.js';
import type { Queryable } from './binding.js';
import { lockAgent, withTransaction, assertWritable } from './db.js';
import { MusterError } from './errors.js';
import { revokeLaunchGrants, revokeTokens, tokenJti } from './identity.js';
import type { RolesConfig } from './roles.js';
import { parsePublicKey } from './signing.js';

export const DEFAULT_PERSISTENT_KEY_DAYS = 90;

/**
 * Operator enrollment of a persistent seat key (design 20.1). The private key is generated by the
 * operator and stored in secrets-vault; Muster only ever sees the public key. With rotate, the seat's
 * previous keys, their tokens, and the launch grants they made are revoked in the same transaction.
 * Enrollment is also the only way to reinstate a revoked (tombstoned) seat. Runs under the admin
 * database role; the muster_api role cannot insert persistent keys (migration 1889).
 */
export async function enrollPersistentKey(
  pool: pg.Pool,
  roles: RolesConfig,
  p: { agentId: string; publicKeyB64: string; expiresInDays?: number; rotate?: boolean; actor: string },
): Promise<{ key_id: string; public_key_sha256: string; expires_at: string; rotated_key_ids: string[]; reinstated: boolean }> {
  const principal = roles.resolve(p.agentId);
  if (principal.persistenceClass !== 'persistent') throw new MusterError(403, 'class_mismatch');
  const key = parsePublicKey(p.publicKeyB64);
  const days = p.expiresInDays ?? DEFAULT_PERSISTENT_KEY_DAYS;
  if (!Number.isInteger(days) || days < 1 || days > 365) throw new MusterError(400, 'invalid_expiry');

  return withTransaction(pool, async (client) => {
    await assertWritable(client);
    await lockAgent(client, p.agentId);
    const active = await client.query<{ key_id: string }>(
      `SELECT key_id FROM agent_bus.principal_keys
        WHERE agent_id = $1 AND key_kind = 'persistent' AND revoked_at IS NULL`,
      [p.agentId],
    );
    if (active.rows.length > 0 && !p.rotate) throw new MusterError(409, 'active_key_exists');

    const { rows } = await client.query<{ key_id: string; expires_at: Date }>(
      `INSERT INTO agent_bus.principal_keys (agent_id, request_id, public_key, public_key_sha256, key_kind, expires_at)
       VALUES ($1, NULL, $2, $3, 'persistent', now() + make_interval(days => $4))
       RETURNING key_id, expires_at`,
      [p.agentId, p.publicKeyB64, key.sha256, days],
    );
    const created = rows[0] as { key_id: string; expires_at: Date };

    const reinstated = await client.query(
      `UPDATE agent_bus.registry_entries SET tombstoned_at = NULL, updated_at = now()
        WHERE agent_id = $1 AND tombstoned_at IS NOT NULL`,
      [p.agentId],
    );
    await audit(client, {
      eventType: 'key_issued',
      agentId: p.agentId,
      actor: p.actor,
      keyId: created.key_id,
      detail: {
        key_kind: 'persistent',
        public_key_sha256: key.sha256,
        expires_at: created.expires_at.toISOString(),
        reinstated: reinstated.rowCount === 1,
      },
    });

    for (const old of active.rows) {
      await client.query(`UPDATE agent_bus.principal_keys SET revoked_at = now() WHERE key_id = $1 AND revoked_at IS NULL`, [old.key_id]);
      await revokeTokens(client, { agentId: p.agentId, keyId: old.key_id }, 'key_rotated', p.actor);
      await revokeLaunchGrants(client, { launcherKeyId: old.key_id }, 'key_rotated', p.actor);
      await audit(client, { eventType: 'key_revoked', agentId: p.agentId, actor: p.actor, keyId: old.key_id, detail: { reason: 'key_rotated' } });
      await audit(client, {
        eventType: 'key_rotated',
        agentId: p.agentId,
        actor: p.actor,
        keyId: created.key_id,
        detail: { previous_key_id: old.key_id },
      });
    }

    return {
      key_id: created.key_id,
      public_key_sha256: key.sha256,
      expires_at: created.expires_at.toISOString(),
      rotated_key_ids: active.rows.map((r) => r.key_id),
      reinstated: reinstated.rowCount === 1,
    };
  });
}

/** Accepts the token itself or its jti (sha256 hex). */
export async function revokeToken(pool: pg.Pool, p: { tokenOrJti: string; reason: string; actor: string }): Promise<{ revoked: number }> {
  const jti = p.tokenOrJti.startsWith('mst_') ? tokenJti(p.tokenOrJti) : p.tokenOrJti;
  const { rows } = await pool.query<{ agent_id: string }>(`SELECT agent_id FROM agent_bus.issued_tokens WHERE jti = $1`, [jti]);
  const row = rows[0];
  if (!row) throw new MusterError(404, 'token_unknown');
  return withTransaction(pool, async (client) => {
    await lockAgent(client, row.agent_id);
    return { revoked: await revokeTokens(client, { agentId: row.agent_id, jti }, p.reason, p.actor) };
  });
}

export async function revokeKey(pool: pg.Pool, p: { keyId: string; reason: string; actor: string }): Promise<{ key_revoked: boolean; tokens_revoked: number; grants_revoked: number }> {
  const { rows } = await pool.query<{ agent_id: string }>(`SELECT agent_id FROM agent_bus.principal_keys WHERE key_id = $1`, [p.keyId]);
  const row = rows[0];
  if (!row) throw new MusterError(404, 'key_unknown');
  return withTransaction(pool, async (client) => {
    await lockAgent(client, row.agent_id);
    const updated = await client.query(`UPDATE agent_bus.principal_keys SET revoked_at = now() WHERE key_id = $1 AND revoked_at IS NULL`, [p.keyId]);
    if (updated.rowCount === 1) {
      await audit(client, { eventType: 'key_revoked', agentId: row.agent_id, actor: p.actor, keyId: p.keyId, detail: { reason: p.reason } });
    }
    const tokens = await revokeTokens(client, { agentId: row.agent_id, keyId: p.keyId }, p.reason, p.actor);
    const grants = await revokeLaunchGrants(client, { launcherKeyId: p.keyId }, p.reason, p.actor);
    return { key_revoked: updated.rowCount === 1, tokens_revoked: tokens, grants_revoked: grants };
  });
}

/** Operator recovery for a stuck or squatted runner id (AR XB-02). */
export async function revokeGrant(pool: pg.Pool, p: { agentId: string; reason: string; actor: string }): Promise<{ grants_revoked: number }> {
  return withTransaction(pool, async (client) => {
    await lockAgent(client, p.agentId);
    return { grants_revoked: await revokeLaunchGrants(client, { agentId: p.agentId }, p.reason, p.actor) };
  });
}

async function revokeOneAgent(client: Queryable, agentId: string, reason: string, actor: string): Promise<{ keys: number; tokens: number }> {
  const keys = await client.query<{ key_id: string }>(
    `UPDATE agent_bus.principal_keys SET revoked_at = now() WHERE agent_id = $1 AND revoked_at IS NULL RETURNING key_id`,
    [agentId],
  );
  for (const k of keys.rows) {
    await audit(client, { eventType: 'key_revoked', agentId, actor, keyId: k.key_id, detail: { reason } });
  }
  const tokens = await revokeTokens(client, { agentId }, reason, actor);
  await revokeLaunchGrants(client, { launcherAgentId: agentId }, reason, actor);
  await revokeLaunchGrants(client, { agentId }, reason, actor);
  // A never-registered id still gets a tombstone, so it cannot register later without operator enrollment.
  await client.query(
    `INSERT INTO agent_bus.registry_entries (agent_id, runtime, persistence_class, ttl_seconds, tombstoned_at)
     SELECT $1, 'worker', 'ephemeral', 60, now()
      WHERE NOT EXISTS (SELECT 1 FROM agent_bus.registry_entries WHERE agent_id = $1)`,
    [agentId],
  );
  await client.query(
    `UPDATE agent_bus.registry_entries SET tombstoned_at = now(), updated_at = now() WHERE agent_id = $1 AND tombstoned_at IS NULL`,
    [agentId],
  );
  return { keys: keys.rows.length, tokens };
}

/**
 * Revokes every key, token, and launch grant of an agent and tombstones it, so it cannot register again
 * until an operator reinstates it. If the agent brokered runners, their credentials are revoked too
 * (AR CA-03); the API also rejects any runner token whose launcher is tombstoned, which covers
 * registrations that race this call.
 */
export async function revokeAgent(pool: pg.Pool, p: { agentId: string; reason: string; actor: string }): Promise<{ keys_revoked: number; tokens_revoked: number; runners_revoked: string[] }> {
  return withTransaction(pool, async (client) => {
    await lockAgent(client, p.agentId);
    const own = await revokeOneAgent(client, p.agentId, p.reason, p.actor);
    const runners = await client.query<{ agent_id: string }>(
      `SELECT DISTINCT requested_agent_id AS agent_id FROM agent_bus.registration_requests
        WHERE launcher_agent_id = $1 AND requested_agent_id <> $1 ORDER BY 1`,
      [p.agentId],
    );
    let keys = own.keys;
    let tokens = own.tokens;
    for (const runner of runners.rows) {
      const r = await revokeOneAgent(client, runner.agent_id, `launcher_revoked: ${p.reason}`, p.actor);
      keys += r.keys;
      tokens += r.tokens;
    }
    return { keys_revoked: keys, tokens_revoked: tokens, runners_revoked: runners.rows.map((r) => r.agent_id) };
  });
}

/**
 * Break glass (design 20.1): revokes every active key, token, and launch grant, then writes the
 * durable read-only flag. Mutating API routes stay frozen until recoverWrites. Registry entries
 * are not tombstoned; the operator re-enrolls seats after recovery.
 */
export async function revokeAll(pool: pg.Pool, p: { reason: string; actor: string }): Promise<{ keys_revoked: number; tokens_revoked: number; grants_revoked: number }> {
  return withTransaction(pool, async (client) => {
    await client.query(`SELECT 1 FROM agent_bus.operational_state WHERE singleton FOR UPDATE`);
    await client.query(`LOCK TABLE agent_bus.issued_tokens, agent_bus.principal_keys, agent_bus.launch_grants IN SHARE ROW EXCLUSIVE MODE`);
    const agents = await client.query<{ agent_id: string }>(
      `SELECT DISTINCT agent_id FROM agent_bus.principal_keys WHERE revoked_at IS NULL
       UNION SELECT DISTINCT agent_id FROM agent_bus.issued_tokens WHERE revoked_at IS NULL ORDER BY 1`,
    );
    let keys = 0;
    let tokens = 0;
    for (const { agent_id } of agents.rows) {
      const revokedKeys = await client.query<{ key_id: string }>(
        `UPDATE agent_bus.principal_keys SET revoked_at = now() WHERE agent_id = $1 AND revoked_at IS NULL RETURNING key_id`,
        [agent_id],
      );
      for (const k of revokedKeys.rows) {
        await audit(client, { eventType: 'key_revoked', agentId: agent_id, actor: p.actor, keyId: k.key_id, detail: { reason: `break_glass: ${p.reason}` } });
      }
      keys += revokedKeys.rows.length;
      tokens += await revokeTokens(client, { agentId: agent_id }, `break_glass: ${p.reason}`, p.actor);
    }
    const grants = await revokeLaunchGrants(client, {}, `break_glass: ${p.reason}`, p.actor);
    await client.query(
      `UPDATE agent_bus.operational_state
          SET read_only = TRUE,
              read_only_set_at = now(),
              read_only_set_by = $1,
              read_only_reason = $2,
              read_only_cleared_at = NULL,
              read_only_cleared_by = NULL
        WHERE singleton`,
      [p.actor, p.reason],
    );
    await audit(client, {
      eventType: 'break_glass',
      agentId: p.actor,
      actor: p.actor,
      detail: { reason: p.reason, keys_revoked: keys, tokens_revoked: tokens, grants_revoked: grants },
    });
    return { keys_revoked: keys, tokens_revoked: tokens, grants_revoked: grants };
  });
}

/** Operator-only recovery: clears the durable break-glass read-only flag. */
export async function recoverWrites(pool: pg.Pool, p: { reason: string; actor: string }): Promise<{ read_only: boolean }> {
  return withTransaction(pool, async (client) => {
    await client.query(`SELECT 1 FROM agent_bus.operational_state WHERE singleton FOR UPDATE`);
    await client.query(
      `UPDATE agent_bus.operational_state
          SET read_only = FALSE,
              read_only_cleared_at = now(),
              read_only_cleared_by = $1
        WHERE singleton`,
      [p.actor],
    );
    await audit(client, {
      eventType: 'writes_recovered',
      agentId: p.actor,
      actor: p.actor,
      detail: { reason: p.reason, via: 'muster-admin' },
    });
    return { read_only: false };
  });
}
